35	\begin{equation}
36	\label{eq:cil-main}
37	\text{CIL}(V, G) = \log_2 \frac{P(V \text{ correct} \mid G \text{ wrong})}{P(V \text{ correct} \mid G \text{ correct})}.
38	\end{equation}
